const conditionalPrerequisites: Partial<Record<McpToolName, readonly string[]>> = {
    "borrower.resolve-and-portfolio": ["Supply exactly one of query or borrowerPublicId; an ambiguous query returns candidates and requires a human to identify the borrower."],
    "borrower.alias": ["For action add, provide borrowerPublicId and alias. For confirm or deactivate, provide aliasPublicId."],
};

const idempotentWithoutKey = new Set<McpToolName>(["payment.post", "payment.reverse"]);

const realErrorGuidance = (toolName: McpToolName): ToolGuidance["commonErrors"] => [{
    code: "INVALID_TOOL_ARGUMENTS",
    recovery: `Check the closed input schema for ${toolName}; satisfy its field, conditional, UUID, date, and decimal-string constraints before retrying.`,
}];

export const TOOL_GUIDANCE: Readonly<Record<McpToolName, ToolGuidance>> = deepFreeze(Object.fromEntries(
    MCP_TOOL_NAMES.map((toolName) => {
        const base = BASE_TOOL_GUIDANCE[toolName];
        const family = workflowFamilies.find((tools) => tools.includes(toolName));
        const relatedTools = family?.filter((related) => related !== toolName).slice(0, 7) ?? [];
        const sideEffects = base.sideEffects.length === 0
            ? []
            : toolName.endsWith(".preview")
                ? [`Persists a ${toolName} review artifact; it does not perform the later financial execution.`]
                : base.sideEffects;
        return [toolName, {
            ...base,
            prerequisites: conditionalPrerequisites[toolName] ?? base.prerequisites,
            sideEffects,
            domain: toolName.startsWith("loan.disbursement.") ? "disbursements" : base.domain,
            retrySafety: base.sideEffects.length === 0
                ? "Safe to repeat with the identical valid arguments; this read does not require an idempotency key."
                : idempotentWithoutKey.has(toolName)
                    ? "Safe to retry the same operation with identical valid arguments; its input schema has no idempotency key."
                    : base.retrySafety,
            requiresHumanConfirmation: explicitlyConfirmedTools.has(toolName),
            commonErrors: realErrorGuidance(toolName),
            relatedTools,
        } satisfies ToolGuidance];
    }),
) as unknown as Record<McpToolName, ToolGuidance>);

export const TOOL_GUIDANCE_VERSION = `mcp-guidance-${hashGuidanceContent(canonicalGuidance()).slice(0, 16)}`;

export function describeTool(toolName: McpToolName): string {
    const guidance = TOOL_GUIDANCE[toolName];
    const effects = guidance.sideEffects.length === 0 ? "No side effects; read-only." : guidance.sideEffects.join(" ");
    const confirmation = guidance.requiresHumanConfirmation ? " Requires explicit human confirmation through the workflow before execution." : "";
    return [guidance.purpose, `Use: ${guidance.whenToUse[0]}`, `Effects: ${effects}`, `Retry: ${guidance.retrySafety}${confirmation}`].join(" ");
}
